// Generated by agent-workstation for a single-use origin-bound WebAuthn lease.
// Private keys never enter this extension; requests are forwarded over the
// per-lease authenticated loopback bridge for browser-process origin checks.

let attached = false;
let detached = false;
let controlSocket = null;

async function safeDetach() {
  if (detached) return;
  detached = true;
  if (controlSocket) {
    try { controlSocket.close(); } catch {}
    controlSocket = null;
  }
  if (!attached) return;
  attached = false;
  try {
    await chrome.webAuthenticationProxy.detach();
  } catch {}
}

function connectControl() {
  const ws = new WebSocket(CONFIG.wsUrl);
  controlSocket = ws;
  ws.addEventListener('open', async () => {
    if (detached) {
      try { ws.close(); } catch {}
      return;
    }
    try {
      await chrome.webAuthenticationProxy.attach();
      attached = true;
      ws.send(JSON.stringify({ type: 'ready', token: CONFIG.token }));
    } catch (err) {
      try {
        ws.send(JSON.stringify({ type: 'error', token: CONFIG.token, message: String(err) }));
      } catch {}
      await safeDetach();
    }
  });
  ws.addEventListener('message', async (event) => {
    try {
      const msg = JSON.parse(String(event.data));
      if (msg && msg.type === 'detach') {
        await safeDetach();
      }
    } catch {}
  });
  ws.addEventListener('close', () => {
    void safeDetach();
  });
  ws.addEventListener('error', () => {
    void safeDetach();
  });
}

chrome.webAuthenticationProxy.onIsUvpaaRequest.addListener(async ({ requestId }) => {
  try {
    await chrome.webAuthenticationProxy.completeIsUvpaaRequest({
      requestId,
      isUvpaa: Boolean(!detached && CONFIG.reportUvpaa),
    });
  } catch {}
});

async function forwardCeremony(kind, requestId, requestDetailsJson) {
  const complete = kind === 'create'
    ? chrome.webAuthenticationProxy.completeCreateRequest.bind(chrome.webAuthenticationProxy)
    : chrome.webAuthenticationProxy.completeGetRequest.bind(chrome.webAuthenticationProxy);

  if (detached) {
    try {
      await complete({
        requestId,
        error: { name: 'NotAllowedError', message: 'WebAuthn ceremony lease is closed' },
      });
    } catch {}
    return;
  }

  let decision = {
    error: { name: 'NotAllowedError', message: 'WebAuthn ceremony bridge unavailable' },
  };
  try {
    const resp = await fetch(CONFIG.requestUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-WebAuthn-Bridge-Token': CONFIG.token,
      },
      body: JSON.stringify({ kind, requestId, requestDetailsJson }),
    });
    if (resp.ok) {
      const body = await resp.json();
      if (body && (typeof body.responseJson === 'string' || (body.error && typeof body.error.name === 'string'))) {
        decision = body;
      }
    }
  } catch {}

  try {
    await complete({ requestId, ...decision });
  } catch {}
  await safeDetach();
}

chrome.webAuthenticationProxy.onCreateRequest.addListener(({ requestId, requestDetailsJson }) => {
  void forwardCeremony('create', requestId, requestDetailsJson);
});

chrome.webAuthenticationProxy.onGetRequest.addListener(({ requestId, requestDetailsJson }) => {
  void forwardCeremony('get', requestId, requestDetailsJson);
});

chrome.webAuthenticationProxy.onRequestCanceled.addListener(() => {
  // Single-use leases tear down fail-closed if the host or page cancels.
});

connectControl();
